function ChevronIcon() {
  return (
    <svg viewBox="0 0 19 11" xmlns="http://www.w3.org/2000/svg" className="cruise-line__chevron">
      <path
        d="M9.49995 10.8305C9.15943 10.8305 8.81895 10.7005 8.55934 10.441L0.389769 2.27137C-0.129923 1.75168 -0.129923 0.909092 0.389769 0.389611C0.90925 -0.12987 1.75167 -0.12987 2.27141 0.389611L9.49995 7.61857L16.7285 0.389863C17.2482 -0.129618 18.0906 -0.129618 18.61 0.389863C19.1299 0.909344 19.1299 1.75193 18.61 2.27163L10.4406 10.4413C10.1808 10.7008 9.84034 10.8305 9.49995 10.8305Z"
        fill="currentColor"
      />
    </svg>
  );
}

function CruiseLine() {
  const [isOpen, setIsOpen] = useState(false);
  const [selected, setSelected] = useState("");
  const rootRef = useRef(null);

  const handleToggle = () => {
    setIsOpen((prev) => !prev);
  };

  const handleSelect = (option) => {
    setSelected(option);
    setIsOpen(false);
  };

  useEffect(() => {
    const handlePointerDown = (event) => {
      if (!rootRef.current?.contains(event.target)) {
        setIsOpen(false);
      }
    };

    document.addEventListener("mousedown", handlePointerDown);
    document.addEventListener("touchstart", handlePointerDown);

    return () => {
      document.removeEventListener("mousedown", handlePointerDown);
      document.removeEventListener("touchstart", handlePointerDown);
    };
  }, []);

  return (
    <div ref={rootRef} className={`cruise-line ${isOpen ? "is-open" : ""}`}>
      {!isOpen && (
        <button
          type="button"
          className="cruise-line__trigger"
          onClick={handleToggle}
          aria-expanded={isOpen}
          aria-haspopup="listbox"
        >
          <span className="cruise-line__icon-box" aria-hidden="true">
            <CruiseLineIcon />
          </span>

          <span className="cruise-line__label">
            {selected || "Cruise Line"}
          </span>

          <span className="cruise-line__chevron-box" aria-hidden="true">
            <ChevronIcon />
          </span>
        </button>
      )}

      {isOpen && (
        <div className="cruise-line__dropdown">
          <button
            type="button"
            className="cruise-line__header"
            onClick={handleToggle}
            aria-expanded={isOpen}
          >
            Cruise Line
          </button>

          <ul className="cruise-line__list" role="listbox" aria-label="Cruise Line options">
            {OPTIONS.map((option) => (
              <li key={option} className="cruise-line__item-wrapper">
                <button
                  type="button"
                  className={`cruise-line__item ${selected === option ? "is-selected" : ""}`}
                  onClick={() => handleSelect(option)}
                >
                  {option}
                </button>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

export default CruiseLine;